package com.transiva.app;
import android.content.Intent;import android.net.Uri;import android.os.Bundle;import android.widget.*;
public class MerchantPrivacyActivity extends MerchantBaseActivity{
 @Override protected void onCreate(Bundle b){super.onCreate(b);LinearLayout root=new LinearLayout(this);setContentView(page(root));root.addView(title("Privasi & Data"));root.addView(sub("Kontrol data dan informasi kebijakan Transiva Merchant"));root.addView(card("Transiva Merchant menggunakan data akun untuk autentikasi dan operasional merchant. Lokasi digunakan untuk menentukan titik pickup. Kamera/galeri digunakan saat Anda memilih gambar menu atau banner. Notifikasi digunakan untuk pembaruan pesanan dan komunikasi operasional."));Button p=btn("Buka Kebijakan Privasi");p.setOnClickListener(v->web("https://transiva.my.id/privacy-policy.html"));root.addView(p);Button d=outlineBtn("Halaman Penghapusan Akun");d.setOnClickListener(v->web("https://transiva.my.id/delete-account.html"));root.addView(d);root.addView(card("Penghapusan akun permanen juga tersedia langsung di Pengaturan Merchant. Riwayat transaksi yang wajib dipertahankan karena kebutuhan hukum/akuntansi harus dijelaskan pada kebijakan retensi sebelum produksi."));}
 private void web(String u){try{startActivity(new Intent(Intent.ACTION_VIEW, Uri.parse(u)));}catch(Exception e){toast("Browser tidak tersedia");}}
}
